-- Run explicitly with `npm run db:migrate`. This migration never imports or deletes SQLite data.
CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user_id_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, type TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', venue TEXT NOT NULL DEFAULT '', map_url TEXT NOT NULL DEFAULT '', start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, timezone TEXT NOT NULL, registration_url TEXT NOT NULL DEFAULT '', dress_code TEXT NOT NULL DEFAULT '', parking TEXT NOT NULL DEFAULT '', organizer_contact TEXT NOT NULL DEFAULT '', archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS events_user_id_idx ON events(user_id);
CREATE TABLE IF NOT EXISTS guests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', rsvp TEXT NOT NULL DEFAULT 'Pending', consent BOOLEAN NOT NULL DEFAULT FALSE, consent_source TEXT NOT NULL DEFAULT '', consent_at TIMESTAMPTZ, suppressed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, UNIQUE(event_id, phone));
CREATE INDEX IF NOT EXISTS guests_user_id_idx ON guests(user_id);
CREATE TABLE IF NOT EXISTS consent_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE, status TEXT NOT NULL, source TEXT NOT NULL, purpose TEXT NOT NULL, recorded_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, body TEXT NOT NULL, approved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, name TEXT NOT NULL, template_id TEXT REFERENCES templates(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'Draft', scheduled_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id TEXT REFERENCES events(id) ON DELETE SET NULL, guest_id TEXT REFERENCES guests(id) ON DELETE SET NULL, campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL, direction TEXT NOT NULL, content TEXT NOT NULL, provider_id TEXT, status TEXT NOT NULL, simulated BOOLEAN NOT NULL DEFAULT FALSE, error TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS suppressions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, phone TEXT NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, phone));
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, provider_event_id TEXT UNIQUE, payload TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL, run_at TIMESTAMPTZ NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Scheduled', attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, action TEXT NOT NULL, subject TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS service_settings (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, whatsapp_number TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, price_paise INTEGER NOT NULL, pricing_type TEXT NOT NULL, description TEXT NOT NULL, inclusions JSONB NOT NULL DEFAULT '[]'::jsonb, add_ons JSONB NOT NULL DEFAULT '[]'::jsonb, availability TEXT NOT NULL DEFAULT 'Available', location TEXT NOT NULL DEFAULT '', published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS services_user_id_idx ON services(user_id);
CREATE TABLE IF NOT EXISTS service_images (id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, filename TEXT NOT NULL, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS booking_requests (id TEXT PRIMARY KEY, reference TEXT UNIQUE NOT NULL, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE RESTRICT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, customer_name TEXT NOT NULL, phone TEXT NOT NULL, event_type TEXT NOT NULL, preferred_date TEXT NOT NULL, location TEXT NOT NULL, guest_count INTEGER NOT NULL, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'New', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
